    "PDF compression canceled. No new file was saved.": "Kompresiraneto na PDF faĭla e otmeneno. Ne e zapazen nov faĭl.\nMostrar más",
    "Optimizing PDF structure on your device…": "Optimizirane na strukturata na PDF faĭla na Vasheto ustroĭstvo…",
    "Rendering page {current} of {total} on your device…": "Generirane na stranitsa {current} ot {total} na Vasheto ustroĭstvo…",
    "Creating the compressed PDF on your device…": "Sŭzdavane na kompresiran PDF faĭl na Vasheto ustroĭstvo…",
    "This method did not make the PDF smaller. The original is unchanged. Try the other mode.": "Tozi metod ne namali razmera na PDF faĭla. Originalŭt ostava nepromenen. Opitaĭte drugiya rezhim.",
    "PDF optimization made the file {size} smaller. Compare it before using it. Your original is unchanged.": "Оптимизацията на PDF намали размера на файла с {size}. Сравнете копието преди употреба. Оригиналът остава непроменен.",
    "Image compression made the file {size} smaller. Inspect readability; the original is unchanged.": "Компресирането намали изображението с {size}. Проверете дали е четливо; оригиналът остава непроменен.",
    "Choose a video": "Izberete videoklip",
    "The video is processed on your device and is never uploaded. There is no fixed file-size cap; available memory, storage and browser codecs set practical limits.": "Videoklipŭt se obrabotva na Vasheto ustroĭstvo i ne se kachva nikŭde. Nyama fiksirano ogranichenie za razmera na faĭla; nalichnata pamet, myastoto za sŭkhranenie i kodetsite na brauzŭra opredelyat prakticheskite granitsi.",
    "MP4 · broadly compatible": "MP4 · shiroka sŭvmestimost",
