    "Keep original resolution": "Zapazvane na originalnata razdelitelna sposobnost",
    "Up to 1080p": "Do 1080p",
    "Up to 720p": "Do 720p",
    "Before you start": "Predi da zapochnete",
    "Compression re-encodes video and may reduce quality. If a format cannot keep an audio, subtitle or data track, processing stops instead of silently removing it. Your original is never changed.": "Kompresiraneto prekodira videoklipa i mozhe da namali kachestvoto mu. Ako daden format ne poddŭrzha audio, subtitri ili potok s danni, obrabotkata spira, vmesto avtomatichno da gi premakhne. Originalniyat faĭl ostava nepromenen.",
    "This browser cannot save the result as a stream, so it will temporarily use device memory. Very large videos may exceed what the browser or device can handle.": "Tozi brauzŭr ne mozhe da zapishe rezultata kato potok, zatova vremenno shte izpolzva pametta na ustroĭstvoto. Mnogo golemi videoklipove mozhe da nadkhvŭrlyat kapatsiteta na brauzŭra ili ustroĭstvoto.",
    "Compress video": "Kompresirane na video",
    "Video compression progress": "Napredŭk na kompresiraneto na videoto",
    "No upload. Keep this tab open while your device works.": "Nyama kachvane. Drŭzhte tozi razdel otvoren, dokato ustroĭstvoto raboti.",
    "Video selected. Choose quality and resolution, then compress.": "Videoklipŭt e izbran. Izberete kachestvo i razdelitelna sposobnost, sled koeto kompresiraĭte.",
    "Choose a video before compressing.": "Izberete videoklip predi kompresirane.",
    "Choose where to save the new video…": "Izberete kŭde da zapishete noviya videoklip…",
    "Encoding video on your device. Keep this tab open…": "Kodirane na videoklipa na ustroĭstvoto. Drŭzhte tozi razdel otvoren…",
    "Compressing video: {percent}%": "Kompresirane na videoklipa: {percent}%",
    "Video saved as a new file, {size} smaller. Your original is unchanged.": "Videoklipŭt e zapisan kato nov faĭl, {size} po-malŭk. Originalŭt ostava nepromenen.",
    "Compressed video is {size} smaller. Review it before sharing; your original is unchanged.": "Kompresiraniyat videoklip e {size} po-malŭk. Pregledaĭte go, predi da go spodelite; originalŭt ostava nepromenen.",
    "This video could not be made smaller. No copy was saved; your original is unchanged. Try a lower quality or resolution.": "Razmerŭt na tozi videoklip ne mozha da bŭde namalen. Ne e zapisano kopie; originalŭt ostava nepromenen. Opitaĭte s po-nisko kachestvo ili razdelitelna sposobnost.",
    "Video compression canceled. No compressed copy was kept.": "Kompresiraneto na videoklipa e otmeneno. Ne e zapazeno kompresirano kopie.",
    "Save was canceled. Your original video is unchanged.": "Zapisvaneto e otmeneno. Originalniyat videoklip ostava nepromenen.\nMostrar más",
    "This video has an audio, subtitle or data track that the selected format cannot keep. No output was saved.": "Tozi videoklip sŭdŭrzha audio, subtitri ili potok ot danni, koito izbraniyat format ne poddŭrzha. Ne beshe zapisan izkhoden faĭl.",
    "No video track was found in this file.": "V tozi faĭl ne beshe otkrit videopotok.",
    "This browser cannot encode the selected video in that format. Try another format or browser.": "Tozi brauzŭr ne mozhe da kodira izbraniya videoklip v tozi format. Opitaĭte s drug format ili brauzŭr.",
    "This browser could not process this video. Try MP4 or WebM, another output format, or a smaller resolution.": "Tozi brauzŭr ne uspya da obraboti videoklipa. Opitaĭte s MP4 ili WebM, drug izkhoden format ili po-niska razdelitelna sposobnost.",
