    "PDFs are processed on this device and are never uploaded. There is no fixed file-size cap; available memory and browser support are the practical limits. Choose up to 10 PDFs to merge.": "PDF faĭlovete se obrabotvat na ustroĭstvoto i ne se kachvat nikŭde. Nyama fiksirano ogranichenie za razmera na faĭla; prakticheskite ogranicheniya zavisyat ot nalichnata pamet i vŭzmozhnostite na brauzŭra. Izberete do 10 PDF faĭla za obedinyavane.",
    "JPG, PNG or WebP. No fixed file-size cap. Very large images depend on device memory; output is limited to 40 megapixels.": "JPG, PNG ili WebP. Nyama fiksirano ogranichenie za razmera na faĭla. Obrabotkata na mnogo golemi izobrazheniya zavisi ot pametta na ustroĭstvoto; izkhodniyat faĭl e ogranichen do 40 megapiksela.",
