    "status.ready": "status.ready",
    "JPG, PNG, WebP, HEIC/HEIF, AVIF, BMP, GIF/APNG, SVG or ICO. Animated files export their first frame. Metadata is not copied.": "JPG, PNG, WebP, HEIC/HEIF, AVIF, BMP, GIF/APNG, SVG ili ICO. Pri animiranite faĭlove se eksportira pŭrviyat kadŭr. Metadannite ne se kopirat.",
    "Transparent areas become white. Animated images use only their first frame.": "Prozrachnite zoni stavat beli. Pri animiranite izobrazheniya se izpolzva samo pŭrviyat kadŭr.",
    "JPG, PNG, WebP, HEIC/HEIF, AVIF, BMP, GIF/APNG, SVG and ICO. Animated files export only their first frame. Output up to 40 megapixels.": "JPG, PNG, WebP, HEIC/HEIF, AVIF, BMP, GIF/APNG, SVG i ICO. Ot animiranite faĭlove se eksportira samo pŭrviyat kadŭr. Izkhodna rezolyutsiya do 40 megapiksela.",
    "Convert common image formats to JPG, PNG or WebP on your device. Up to 20 files.": "Konvertiraĭte chesto sreshtani formati izobrazheniya v JPG, PNG ili WebP direktno na ustroĭstvoto si. Do 20 faĭla.",
    "Add up to 20 images. No fixed file-size cap; 20 megapixels per image. Large batches depend on your device memory.": "Dobavete do 20 izobrazheniya. Nyama fiksirano ogranichenie za razmera na faĭla; do 20 megapiksela na izobrazhenie. Obrabotkata na golemi grupi faĭlove zavisi ot pametta na ustroĭstvoto vi.",
    "Images converted. Animated files become a still frame; metadata is not copied.": "Izobrazheniyata sa konvertirani. Animiranite faĭlove se prevrŭshtat v statichen kadŭr; metadannite ne se kopirat.",
    "Some files were skipped. Use a supported image format within the on-page limits.": "Nyakoi faĭlove byakha propusnati. Izpolzvaĭte poddŭrzhan format na izobrazhenieto v ramkite na ogranicheniyata na stranitsata.",
    "This image could not be decoded by your browser. Try another file or browser.": "Tova izobrazhenie ne mozha da bŭde dekodirano ot brauzŭra vi. Opitaĭte s drug faĭl ili brauzŭr.",
    "Choose a supported image format.": "Izberete poddŭrzhan format na izobrazhenieto.",
    "The browser does not support the selected output format.": "Brauzŭrŭt ne poddŭrzha izbraniya izkhoden format.",
    "Up to 20 images · 20 megapixels per image · no fixed file-size cap. Large batches depend on your device memory.": "Do 20 izobrazheniya · 20 megapiksela na izobrazhenie · bez fiksirano ogranichenie za razmera na faĭla. Obrabotkata na golemi grupi faĭlove zavisi ot pametta na ustroĭstvoto vi.",
    "Choose up to 20 images.": "Izberete do 20 izobrazheniya.",
    "AVIF and some HEIC files may depend on browser support.": "Poddrŭzhkata na AVIF i nyakoi HEIC faĭlove mozhe da zavisi ot brauzŭra.",
    "AVIF and some HEIC inputs depend on browser support. Animated GIF, APNG and WebP files become a still image. SVG is rasterized, not converted into an editable vector. Metadata is not copied.": "Poddrŭzhkata na AVIF i nyakoi HEIC faĭlove zavisi ot brauzŭra. Animiranite GIF, APNG i WebP faĭlove se prevrŭshtat v statichni izobrazheniya. SVG se rasterizira, a ne se konvertira vŭv vektor s vŭzmozhnost za redaktirane. Metadannite ne se kopirat.\nMostrar más",
    "Multi-page TIFF uses only its first page. Some TIFF compression variants may not decode.": "Ot mnogostranichen TIFF faĭl se izpolzva samo pŭrvata stranitsa. Vŭzmozhno e nyakoi varianti na TIFF kompresiya da ne mogat da bŭdat dekompresirani.",
    "Choose a DOCX, XLSX or PPTX file": "Izberete DOCX, XLSX ili PPTX faĭl",
    "Files stay on your device. Limits: 100 MB input, 200 MB expanded data and 5,000 package parts.": "Faĭlovete ostavat na ustroĭstvoto vi. Ogranicheniya: 100 MB za vkhodniya faĭl, 200 MB za razarkhiviranite danni i 5000 komponenta v paketa.",
    "This safely recompresses the Office package without rewriting its contents. Embedded photos are not recompressed, so the result may not be smaller. Signed, encrypted, macro-enabled and older Office files are not supported. Keep your original.": "Tova bezopasno prekompresira Office paketa, bez da promenya sŭdŭrzhanieto mu. Vgradenite snimki ne se prekompresirat, taka che kraĭniyat faĭl mozhe da ne e po-malŭk. Podpisani, kriptirani ili po-stari Office faĭlove, kakto i takiva s makrosi, ne se poddŭrzhat. Zapazete originalniya faĭl.",
    "Try to reduce file size": "Opitaĭte da namalite razmera na faĭla",
    "Processing runs locally in this browser. No upload.": "Obrabotkata se izvŭrshva lokalno v brauzŭra. Faĭlŭt ne se kachva v internet.",
    "Recompressing the Office package on your device…": "Prekompresirane na Office paketa na ustroĭstvoto vi...",
    "This package is already compact. No smaller download was created.": "Tozi paket veche e kompakten. Ne e sŭzdaden po-malŭk faĭl za izteglyane.",
    "A smaller copy is ready. Compare it and keep your original.": "Gotovo e kopie s po-malŭk razmer. Sravnete go i zapazete originala.",
    "The file could not be safely recompressed. Your original has not changed.": "Faĭlŭt ne mozha da bŭde bezopasno prekompresiran. Originalniyat faĭl ostava nepromenen.",
    "Processing canceled. Your original file is unchanged.": "Obrabotkata e otmenena. Originalniyat faĭl ostava nepromenen.",
    "Choose a modern DOCX, XLSX or PPTX file.": "Izberete sŭvremenen DOCX, XLSX ili PPTX faĭl.",
    "This file is larger than the 100 MB local processing limit.": "Tozi faĭl nadvishava limita ot 100 MB za lokalna obrabotka.",
    "The expanded package exceeds the 200 MB local processing limit.": "Razarkhiviraniyat paket nadvishava limita ot 200 MB za lokalna obrabotka.",
    "Encrypted Office packages are not supported.": "Kriptirani Office paketi ne se poddŭrzhat.",
    "Signed or macro-enabled Office files are not supported, to avoid invalidating signatures or macros.": "Podpisani Office faĭlove ili takiva s makrosi ne se poddŭrzhat, za da se izbegne narushavane na validnostta na podpisite ili makrosite.",
    "The selected file is not a valid modern Office document of that type.": "Izbraniyat faĭl ne e validen moderen dokument na Office ot tozi tip.",
