    "Audio compression: {percent}%": "Kompresirane na audio: {percent}%",
    "Done. The compressed copy is {size} smaller. Check the sound; your original is unchanged.": "Gotovo. Kompresiranoto kopie e {size} po-malko. Proverete zvuka; originalŭt vi ostava nepromenen.",
    "No smaller audio copy was created. Your original is unchanged.": "Ne beshe sŭzdadeno po-malko audiokopie. Originalŭt vi ostava nepromenen.",
    "Processing canceled. Your original is unchanged.": "Obrabotkata e otmenena. Originalŭt vi ostava nepromenen.",
