    "The first use loads about 6.6 MB from this site. The photo is processed on your device. A computer is recommended for large images.": "Pri pŭrvoto izpolzvane se zarezhdat okolo 6,6 MB ot tozi saĭt. Snimkata se obrabotva na Vasheto ustroĭstvo. Za golemi izobrazheniya se preporŭchva izpolzvaneto na kompyutŭr.",
