    "Ready to remove the background.": "Gotovo za premakhvane na fona.",
    "Portrait image must be 20 megapixels or smaller. Resize it before processing.": "Portretnata snimka tryabva da bŭde s rezolyutsiya 20 megapiksela ili po-malka. Preorazmerete ya predi obrabotka.",
    "Background removal complete. Review the edges before using the image.": "Premakhvaneto na fona priklyuchi. Proverete kraishtata, predi da izpolzvate izobrazhenieto.",
