    "Choose a file": "Изберете файл",
    "Office files stay on your device. Layout, formulas, charts, animations, fonts and page breaks may change. Office to PDF opens your browser’s print dialog. Use a computer for large files.": "Faĭlovete na Office ostavat na Vasheto ustroĭstvo. Vŭzmozhni sa promeni v oformlenieto, formulite, diagramite, animatsiite, shriftovete i prekŭsvaniyata na stranitsi. Funktsiyata „Office kŭm PDF“ otvarya dialogoviya prozorets za pechat na Vashiya brauzŭr. Izpolzvaĭte kompyutŭr za golemi faĭlove.",
    "PDF to Excel estimates rows from selectable text; it does not recreate formulas or tables. PDF to PowerPoint makes image-only slides. Scanned PDFs need OCR first.": "Funktsiyata „PDF kŭm Excel“ opredelya redovete vŭz osnova na izbiraemiya tekst; tya ne vŭzstanovyava formuli ili tablitsi. Funktsiyata „PDF kŭm PowerPoint“ sŭzdava slaĭdove, sŭdŭrzhashti samo izobrazheniya. Skaniranite PDF faĭlove iziskvat predvaritelna obrabotka s OCR.",
    "Office print view opened. Check it, then choose Save as PDF in the browser.": "Otvoren e izgledŭt za pechat na Office. Proverete go i izberete optsiyata za zapisvane kato PDF v brauzŭra.",
