    "Copied to clipboard.": "Kopirano v klipborda.",
    "Copy was blocked. Select the text and copy it manually.": "Kopiraneto beshe blokirano. Markiraĭte teksta i go kopiraĭte rŭchno.",
    "Text file downloaded.": "Tekstoviyat faĭl e izteglen.",
    "This file or codec could not be processed. Try another supported format.": "Faĭlŭt ili kodekŭt ne mozhakha da bŭdat obraboteni. Opitaĭte s drug poddŭrzhan format.",
    "For long or high-resolution media, a desktop or laptop is recommended. Keep this tab open; speed, memory and battery depend on your device.": "Za dŭlgi faĭlove ili takiva s visoka razdelitelna sposobnost se preporŭchva izpolzvaneto na nastolen kompyutŭr ili laptop. Drŭzhte tozi razdel otvoren; skorostta, pametta i bateriyata zavisyat ot Vasheto ustroĭstvo.",
    "Re-encoding can reduce sound quality or make a larger file. Your original stays unchanged.": "Prekodiraneto mozhe da namali kachestvoto na zvuka ili da uvelichi razmera na faĭla. Originalniyat faĭl ostava nepromenen.",
    "First use downloads about 58 MB of model and local engine. Your recording is not uploaded; the browser may download them again if its cache is cleared.": "Pri pŭrvonachalno izpolzvane se izteglyat okolo 58 MB danni za modela i lokalniya mekhanizŭm za obrabotka. Vashiyat zapis ne se kachva v internet; brauzŭrŭt mozhe da gi iztegli otnovo, ako keshŭt mu bŭde izchisten.",
