    "Up to 200 files; 100 MB total or expanded. ZIP64 and password-protected files are not supported. Large archives use device memory; a computer is recommended.": "Do 200 faĭla; obshto 100 MB (v kompresiran ili razarkhiviran vid). Formatŭt ZIP64 i faĭlovete, zashtiteni s parola, ne se poddŭrzhat. Golemite arkhivi izpolzvat pametta na ustroĭstvoto; preporŭchva se izpolzvaneto na kompyutŭr.",
