    "Illustration only; actual returns vary and are not guaranteed. Taxes, inflation and fees are excluded.": "Samo za ilyustratsiya; deĭstvitelnata vŭzvrŭshtaemost varira i ne e garantirana. Danŭtsite, inflatsiyata i taksite sa izklyucheni.",
